"use strict";var Home=function(n){var t={initialize:function(){t.initEvent();t.registerLoginDialog()},initEvent:function(){n("#loginLink").on("click",function(){n("#loginDialog").modal({backdrop:"static"})});n("#btnDialogLogin").on("click",function(){Login.requestSignin(!0)});n("#dialogUserInput input").on("keypress",function(n){n.keyCode===13&&Login.requestSignin(!0)})},registerLoginDialog:function(){n("#loginDialog").on("show.bs.modal",function(){t.generateCaptcha()});n("#loginDialog").on("hide.bs.modal",function(){n("#loginDialogcaptchaImg").attr("src","");Login.generateCaptcha()})},generateCaptcha:function(){var t=Site.resolveRelativeUrl("Home/CaptchaImage?_v="+(new Date).getTime());n("#loginDialogcaptchaImg").attr("src",t)}};return t}(jQuery);Home.initialize();